INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(6501, 'Judges 16:29', 'Judges', 16, 29, '&nbsp;نو سمسون هغه دوه مينځنۍ ستنې ونيولې چې په کومو باندې هغه آبادى ولاړه وه. په دواړو باندې يې يو يو لاس کېښودو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6502, 'Judges 16:30', 'Judges', 16, 30, '&nbsp;او چغه يې کړه، ”پرېږده چې د فلستيانو سره مړ شم.“ هغۀ د خپل ټول زور سره ستنو له ديکه ورکړه او هغه بُت‌خانه په هغه پينځو بادشاهانو او په نورو ټولو کسانو باندې راوغورزېده. سمسون د خپل مرګ په وخت د هغې نه زيات خلق ووژل چې څومره هغۀ په خپل ژوند کښې وژلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6503, 'Judges 16:31', 'Judges', 16, 31, '&nbsp;د هغۀ وروڼه او د هغۀ د خاندان نور کسان د هغۀ لاش وړلو له راغلل. هغه يې واپس يوړو او د صُرعا او اِستال په مينځ کښې د خپل پلار منوحه په قبر کښې يې ښخ کړو. هغه شل کاله د بنى اِسرائيلو قاضى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6504, 'Judges 17:1', 'Judges', 17, 1, '&nbsp;يو ځل يو سړے وو چې نوم يې ميکاه وو، هغه د غرونو په مُلک اِفرائيم کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6505, 'Judges 17:2', 'Judges', 17, 2, '&nbsp;هغۀ خپلې مور ته ووئيل، ”کله چې ستا نه هغه يوولس سوه د سپينو زرو سيکې چا پټې کړې، نو ما واورېدل چې تا هغه غل ته ښېرې وکړې. ګوره، هغه پېسې ما سره دى او هغه ما اخستې دى.“ د هغۀ مور ووئيل، ”زما زويه، مالِک خُدائ دې تا له برکت درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6506, 'Judges 17:3', 'Judges', 17, 3, '&nbsp;هغۀ پېسې واپس خپلې مور له ورکړې او مور يې ووئيل، ”چې هغه ښېرې زما په زوئ باندې ونۀ لګى زۀ پخپله دا د سپينو زرو سيکې مالِک خُدائ ته وقف کوم. د لرګى په يوه مجسمه به دا سپين زر وخېژولے شى. نو داسې به زۀ دا د سپينو زرو سيکې تا له واپس درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6507, 'Judges 17:4', 'Judges', 17, 4, '&nbsp;کله يې چې دا واپس خپلې مور له ورکړې نو هغې دوه سوه د سپينو زرو سيکې يوړې او زرګر د لرګى بُت جوړ کړو او سپين زر يې پرې وخېژول. دا د ميکاه په کور کښې کېښودے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6508, 'Judges 17:5', 'Judges', 17, 5, '&nbsp;د دې سړى يعنې د ميکاه يوه بُت‌خانه وه. هغۀ څۀ بُتان او يو مقدس پېش بند جوړ کړو. او خپل يو زوئ يې خپل اِمام مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6509, 'Judges 17:6', 'Judges', 17, 6, '&nbsp;په هغه وخت کښې په بنى اِسرائيلو کښې يو بادشاه هم نۀ وو، خلقو هم هغه شان کول چې څۀ يې خوښه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6510, 'Judges 17:7', 'Judges', 17, 7, '&nbsp;هم په هغه وخت کښې هلته يو ځوان ليوى وو چې د يهوداه د بيت‌لحم په ښار کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6511, 'Judges 17:8', 'Judges', 17, 8, '&nbsp;هغه د بيت‌لحم نه لاړو چې د اوسېدو دپاره بل ځائ ولټوى. د سفر په دوران کښې د اِفرائيم د غرونو په مُلک کښې د ميکاه کور ته راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6512, 'Judges 17:9', 'Judges', 17, 9, '&nbsp;ميکاه د هغۀ نه تپوس وکړو، ”تۀ د کوم ځائ نه راغلے يې؟“ هغۀ ورته ووئيل، ”زۀ يو ليوى يم چې د يهوداه د بيت‌لحم نه راغلے يم. زۀ د اوسېدو دپاره يو ځائ لټوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6513, 'Judges 17:10', 'Judges', 17, 10, '&nbsp;ميکاه ووئيل، ”ما سره ايسار شه. زما اِمام او مشير شه او زۀ به په کال کښې لس د سپينو زرو سيکې، جامې او خوراک درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6514, 'Judges 17:11', 'Judges', 17, 11, '&nbsp;هغه ځوان ليوى د ميکاه سره اوسېدو ته راضى شو او د هغۀ د زوئ په شان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6515, 'Judges 17:12', 'Judges', 17, 12, '&nbsp;ميکاه هغه خپل اِمام مقرر کړو او هغه د ميکاه په کور کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6516, 'Judges 17:13', 'Judges', 17, 13, '&nbsp;ميکاه ووئيل، ”اوس چې زما يو ليوى اِمام شته، نو ما ته پته ده چې مالِک خُدائ به زما هر کار سم کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6517, 'Judges 18:1', 'Judges', 18, 1, '&nbsp;په هغه وخت کښې چې د بنى اِسرائيلو يو بادشاه هم نۀ وو نو په هغه ورځو کښې د دان قبيلې يوه داسې علاقه لټوله چې دعوىٰ پرې وکړى او قبضه يې کړى ځکه چې د بنى اِسرائيلو په قبيلو کښې هغوئ ته خپله زمکه نۀ وه مِلاو شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6518, 'Judges 18:2', 'Judges', 18, 2, '&nbsp;نو د دان د قبيلې د ټولو کورَنو نه پينځۀ تکړه سړى خوښ کړل. هغوئ يې د صُرعا او اِستال ښارونو نه ولېږل او ورته يې ووئيل چې، ”د هغه مُلک تحقيق وکړئ او ويې لټوئ.“ کله چې هغوئ د غرونو مُلک اِفرائيم ته ورسېدل، نو هغوئ د ميکاه په کور کښې ايسار شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6519, 'Judges 18:3', 'Judges', 18, 3, '&nbsp;کله چې هغوئ هلته وُو، نو هغوئ د هغه ځوان ليوى په لهجه باندې پوهه شول، نو هغوئ ورغلل او تپوس يې ترې نه وکړو، ”تۀ دلته څۀ کوې؟ تۀ دلته چا راوستلے يې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6520, 'Judges 18:4', 'Judges', 18, 4, '&nbsp;هغۀ جواب ورکړو، ”زۀ د ميکاه سره کار کوم، زۀ د اِمام په توګه د هغۀ سره خِدمت کوم او هغه ما له تنخواه راکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6521, 'Judges 18:5', 'Judges', 18, 5, '&nbsp;هغوئ هغۀ ته ووئيل، ”د خُدائ پاک نه لږ تپوس وکړه چې مونږ به په خپل سفر کښې کامياب شُو او کۀ نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6522, 'Judges 18:6', 'Judges', 18, 6, '&nbsp;اِمام جواب ورکړو، ”په خېر لاړ شئ، ستاسو سفر د مالِک خُدائ نه منظور شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6523, 'Judges 18:7', 'Judges', 18, 7, '&nbsp;نو هغه پينځۀ سړى روان شول او د ليس ښار ته لاړل. هغوئ وليدل چې د هغه ځائ خلق د صيدانيانو په شان په امن سره اوسېدل. هغوئ امن پسند او غلى خلق وُو، د هيچا سره يې هم لانجه نۀ وه، هغوئ سره د ضرورت ټول څيزونه موجود وُو. هغوئ د صيدانيانو نه ښۀ لرې اوسېدل او د نورو خلقو سره يې هيڅ لېن دېن نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6524, 'Judges 18:8', 'Judges', 18, 8, '&nbsp;کله چې هغه پينځۀ سړى صُرعا او اِستال ته راوګرځېدل، نو د دوئ خپلوانو د هغوئ نه تپوس وکړو چې، ”تاسو څۀ وليدل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6525, 'Judges 18:9', 'Judges', 18, 9, '&nbsp;هغوئ جواب ورکړو، ”راځئ چې په ليس حمله وکړُو. مونږ هغه مُلک وليدو او هغه ډېر ښۀ وو. دلته هسې مۀ ايسارېږئ. زر شئ. او هغه مُلک ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6526, 'Judges 18:10', 'Judges', 18, 10, '&nbsp;کله چې تاسو هلته ورسېږئ، نو تاسو به وګورئ چې هغه امن پسند خلق دى. هغه يو لوئ مُلک دے، او چې څۀ غواړئ هغه هر څۀ په کښې شته او خُدائ پاک هغه تاسو له درکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6527, 'Judges 18:11', 'Judges', 18, 11, '&nbsp;نو د دان قبيلې شپږ سوه سړى د صُرعا او اِستال نه لاړل او د جنګ وسله ورسره وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6528, 'Judges 18:12', 'Judges', 18, 12, '&nbsp;هغوئ لاړل او د يهوداه په مغرب په قِريَت‌يعريم کښې يې خېمې ولګولې. نو دا ځکه د هغه ځائ نوم تر اوسه پورې د ”دان کېمپ“ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6529, 'Judges 18:13', 'Judges', 18, 13, '&nbsp;هغوئ د هغه ځائ نه لاړل او د غرونو په مُلک اِفرائيم کښې د ميکاه کور ته راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6530, 'Judges 18:14', 'Judges', 18, 14, '&nbsp;بيا هغه پينځۀ سړى کوم چې د ليس مُلک کتلو له تلى وُو هغوئ خپلو ملګرو ته ووئيل، ”تاسو ته پته وه څۀ چې هلته په يو کور کښې يوه مجسمه او يو په قالب کښې جوړ شوے بُت دے؟ هلته نور بُتان او مقدس پېش بند هم دى. ستاسو څۀ خيال دے چې څۀ وکړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6531, 'Judges 18:15', 'Judges', 18, 15, '&nbsp;هغوئ د ميکاه کور ته لاړل، چرته چې هغه ځوان ليوى اوسېدو او سلام يې ورباندې واچولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6532, 'Judges 18:16', 'Judges', 18, 16, '&nbsp;په دې دوران کښې چې د دان کوم شپږ سوه فوجيان چې د جنګ دپاره تيار وُو، هغوئ په دروازه کښې ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6533, 'Judges 18:17', 'Judges', 18, 17, '&nbsp;هغه پينځۀ جاسوسان سيدها کور ته ننوتل او هغه ټول بُتان او مقدس پېش بند يې واخستلو، په دې دوران کښې اِمام د شپږ سوو وسله بندو سړو سره په دروازه کښې ايسار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6534, 'Judges 18:18', 'Judges', 18, 18, '&nbsp;کله چې سړى د ميکاه کور ته ننوتل او مقدس څيزونه يې راواخستل، نو اِمام د هغوئ نه تپوس وکړو، ”تاسو څۀ کوئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6535, 'Judges 18:19', 'Judges', 18, 19, '&nbsp;هغوئ ورته ووئيل، ”غلے شه. چې يوه خبره هم ونۀ کړې. مونږ سره لاړ شه او زمونږ اِمام او مشر شه. د يو سړى د خاندان د اِمام کېدو نه دا ښه نۀ ده څۀ چې د بنى اِسرائيلو د يوې قبيلې اِمام شې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6536, 'Judges 18:20', 'Judges', 18, 20, '&nbsp;نو اِمام په دې باندې ډېر خوشحاله شو او هغه مقدس څيزونه يې واخستل او د هغوئ سره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6537, 'Judges 18:21', 'Judges', 18, 21, '&nbsp;نو هغوئ خپل بچى، څاروى او خپل هر څۀ د ځان نه مخکښې کړل او روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6538, 'Judges 18:22', 'Judges', 18, 22, '&nbsp;هغوئ د هغه کور نه ښۀ لرې مزل کړے وو نو ميکاه خپل ګاونډيان راغونډ کړل او د دان په سړو پسې لاړل او ورورسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6539, 'Judges 18:23', 'Judges', 18, 23, '&nbsp;او هغوئ ته يې چغه کړه. د دان سړى راوګرځېدل او د ميکاه نه يې تپوس وکړو، ”څۀ چل دے چې دومره ډېر خلق راغونډ شوى يئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6540, 'Judges 18:24', 'Judges', 18, 24, '&nbsp;ميکاه ورته په جواب کښې ووئيل، ”مطلب دې څۀ دے، څۀ خبره ده؟ تۀ زما اِمام بوځې او زما جوړ کړى معبودان اوړې او ځې نو نور زما سره څۀ پاتې کيږى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6541, 'Judges 18:25', 'Judges', 18, 25, '&nbsp;د دان سړو ورته ووئيل، ”ستا دپاره به دا ښۀ وى چې نور هيڅ غږ ونۀ کړې. ګنې دا سړى به غصه شى او حمله به درباندې وکړى او بيا به تۀ او ستا ټول خاندان مړۀ شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6542, 'Judges 18:26', 'Judges', 18, 26, '&nbsp;نو هغوئ په خپله مخه لاړل. ميکاه ته پته ولګېده چې د دان سړى په هغوئ باندې ډېر زيات تکړه دى، نو هغه راوګرځېدو او کور ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6543, 'Judges 18:29', 'Judges', 18, 29, '&nbsp;هغوئ د دې نوم د ليس نه دان ته بدل کړو، دان د هغوئ پلار نيکۀ او د يعقوب زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6544, 'Judges 18:30', 'Judges', 18, 30, '&nbsp;د دان خلقو د ځان دپاره جوړ شوے بُت ولګول، او د موسىٰ نمسى او د جيرسوم زوئ يونتن او د هغۀ زامنو تر هغې پورې د اِمامانو په توګه خِدمت کولو چې جلاوطنۍ ته بوتلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6545, 'Judges 18:31', 'Judges', 18, 31, '&nbsp;تر کومې پورې چې د خُدائ پاک کور په سيلا کښې وو نو تر هغه وخته پورې د ميکاه بُت هلته وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6546, 'Judges 19:1', 'Judges', 19, 1, '&nbsp;په هغه ورځو کښې د بنى اِسرائيلو بادشاه نۀ وو او يو ليوے چې د اِفرائيم د غرونو په مُلک کښې ډېر لرې اوسېدو، هغۀ د يهوداه د بيت‌لحم نه يوه وينځه بوتله چې ښځه يې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6547, 'Judges 19:2', 'Judges', 19, 2, '&nbsp;خو هغه د هغۀ نه خفه شوه، په بيت‌لحم کښې واپس د خپل پلار کور ته لاړه او څلور مياشتې يې هلته تېرې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6548, 'Judges 19:3', 'Judges', 19, 3, '&nbsp;بيا هغه سړى دا فېصله وکړه چې هغې پسې لاړ شى او رضا يې کړى چې واپس هغۀ له راشى. هغۀ خپل نوکر او دوه خرونه ځان سره بوتلل. نو کله چې هغه هلته ورسېدو نو ښځې هغه د خپل پلار کور ته راوستو او چې سخر هغه وليدو نو ورته يې ډېر په مينه پخېر راغلے ووئيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6549, 'Judges 19:4', 'Judges', 19, 4, '&nbsp;د هغۀ سخر پرې زور واچولو چې ايسار شى، نو هغه درې ورځې هلته پاتې شو. هغوئ هلته خوراک څښاک وکړو او درې شپې يې تېرې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6550, 'Judges 19:5', 'Judges', 19, 5, '&nbsp;د څلورمې ورځې په سحر هغوئ وختى پاڅېدل او د تلو تيارے يې وکړو. خو د ښځې پلار هغه ليوى ته ووئيل، ”وړومبے لږ څۀ وخوره. چې تازه دم شې نو وروستو به بيا لاړ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6551, 'Judges 19:6', 'Judges', 19, 6, '&nbsp;نو هغه دواړه سړى کښېناستل او په يو ځائ يې خوراک څښاک وکړو. د ښځې پلار بيا هغۀ ته ووئيل، ”دا به ښۀ وى چې شپه دلته تېره کړې او خپل زړۀ خوشحاله کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6552, 'Judges 19:7', 'Judges', 19, 7, '&nbsp;ليوے پاڅېدو چې لاړ شى، خو د هغۀ سخر ورته مِنت وکړو چې ايسار شى، نو هغۀ يوه بله شپه هم هلته تېره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6553, 'Judges 19:8', 'Judges', 19, 8, '&nbsp;په پينځمه ورځ سحر وختى هغه روان شو، خو سخر ورته ووئيل، ”لږ څۀ وخوره او مازيګر پورې صبر وکړه.“ نو دواړو سړو يو ځائ روټۍ وخوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6554, 'Judges 19:9', 'Judges', 19, 9, '&nbsp;کله چې هغه سړے، د هغۀ وينځه او د هغۀ نوکر يو ځل بيا روان شول، نو سخر ورته ووئيل، ”وګوره، ماښام نزدې دے، په کار دى چې تاسو ټوله شپه پاتې شئ. زر به تيارۀ شى، دلته پاتې شئ او خپل زړۀ خوشحاله کړئ. سحر د سفر دپاره وختى پاڅئ او خپل کور ته لاړ شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6555, 'Judges 19:14', 'Judges', 19, 14, '&nbsp;نو هغوئ د يبوس نه تېر شول او په خپله مخه روان وُو. نمر په پرېوتو وو چې هغوئ د بنيامين په علاقه کښې جبعې ته راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6556, 'Judges 19:15', 'Judges', 19, 15, '&nbsp;هغوئ د شپې تېرولو دپاره ورغلل. هغوئ ښار ته لاړل او په بازار کښې کښېناستل، خو هيچا د شپې دپاره کور ته بونۀ تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6557, 'Judges 19:16', 'Judges', 19, 16, '&nbsp;څۀ وخت چې هغوئ هلته وُو، نو يو بوډا سړے راغلو چې ټوله ورځ يې په پټو کښې کار کړے وو. په اصل کښې هغه د اِفرائيم د غرونو د مُلک وو، خو اوس په جبعه کښې اوسېدو. (هلته نور خلق د بنيامين د قبيلې وُو.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6558, 'Judges 19:17', 'Judges', 19, 17, '&nbsp;هغه بوډا سړى د ښار په بازار کښې مسافر وليدو او تپوس يې ترې نه وکړو، ”تۀ د کوم ځائ نه راغلے يې؟ او تۀ چرته ځې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6559, 'Judges 19:18', 'Judges', 19, 18, '&nbsp;ليوى جواب ورکړو، ”مونږ د يهوداه په بيت‌لحم کښې وُو او اوس مونږ د اِفرائيم د غرونو مُلک لرې برخې ته روان يُو د کوم نه چې زۀ راغلے يم. خو داسې هيڅ څوک هم نشته چې مونږ خپل کور ته بوځى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6560, 'Judges 19:19', 'Judges', 19, 19, '&nbsp;زمونږ سره د خپلو خرونو دپاره واښۀ او بوس هم شته او داسې زما، زما د بلې ښځې او زما د نوکر دپاره روټۍ او مے هم شته. ما سره د ضرورت هر يو څيز موجود دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6561, 'Judges 19:20', 'Judges', 19, 20, '&nbsp;هغه بوډا سړى ورته ووئيل، ”په خېر راغلئ. زۀ به ستاسو د هر ضرورت خيال ساتم، تاسو په بازار کښې شپه مۀ تېروئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6562, 'Judges 19:21', 'Judges', 19, 21, '&nbsp;نو هغوئ يې د ځان سره کور ته بوتلل او د هغوئ خرونو له يې خوراک ورکړو. بيا هغوئ خپلې پښې ووينځلې او روټۍ يې وخوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6563, 'Judges 19:22', 'Judges', 19, 22, '&nbsp;هغوئ خپل زړونه خوشحالول چې د ښار څۀ بدکاره سړى ناڅاپه د کور نه تاو شول او په دروازه وهلو باندې يې شروع وکړه. هغوئ هغه بوډا سړى ته ووئيل، ”هغه سړے راوباسه چې تا سره کور ته راغلے دے. مونږ د هغۀ سره حرامکارى کول غواړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6564, 'Judges 19:23', 'Judges', 19, 23, '&nbsp;خو هغه بوډا سړے بهر ورووتلو او ورته يې ووئيل، ”نه، زما وروڼو، زۀ تاسو ته مِنت کوم چې داسې خراب او بې‌اخلاقه کار مۀ کوئ. دا سړے زما مېلمه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6565, 'Judges 19:24', 'Judges', 19, 24, '&nbsp;ګورئ، دلته د هغۀ وينځه او زما لور ده چې وادۀ شوې نۀ ده. زۀ به اوس هغوئ ستاسو دپاره بهر راوباسم او څۀ مو چې خوښه وى ورسره يې وکړئ، خو د دې سړى سره داسې بد کار مۀ کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6566, 'Judges 19:25', 'Judges', 19, 25, '&nbsp;خو هغه سړو د هغۀ خبره نۀ منله. نو ليوى خپله وينځه بهر ورولېږله. نو هغوئ ورسره په زور زنا وکړه او ټوله شپه يې د هغې بې‌عزتى وکړه او په سحر کښې يې پرېښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6567, 'Judges 19:26', 'Judges', 19, 26, '&nbsp;د سحر په رڼا کښې هغه ښځه راغله او د هغه بوډا سړى د کور په دروازه کښې وغورزېدله، چرته يې چې خاوند وو. د نمر راختلو پورې هغه هلته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6568, 'Judges 19:27', 'Judges', 19, 27, '&nbsp;سحر د هغې خاوند پاڅېدو او کله چې هغۀ دروازه کولاو کړه چې په خپله مخه لاړ شى، نو هغۀ د کور په مخکښې خپله وينځه وليده چې د دروازې په خولۀ کښې پرَته وه او لاسونه يې درشل ته رسېدلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6569, 'Judges 19:28', 'Judges', 19, 28, '&nbsp;هغۀ ورته ووئيل، ”پاڅه، راځه چې ځُو.“ خو هغې جواب ورنۀ کړو. نو د هغې لاش يې په خر باندې واچولو او په خپله مخه کور ته روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6570, 'Judges 19:29', 'Judges', 19, 29, '&nbsp;کله چې هغه ورسېدو، نو هغه کور ته دننه لاړو او چاقُو يې راواخستلو. هغۀ د خپلې وينځې لاش واخستلو، دولس ټوټې يې ترې نه جوړې کړې او يوه يوه ټوټه يې د بنى اِسرائيلو دولسو قبيلو له ولېږله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6571, 'Judges 19:30', 'Judges', 19, 30, '&nbsp;هر چا به چې دا وليدل نو وئيل يې، ”د کله نه چې بنى اِسرائيل د مِصر نه راوتلى دى، نو مونږ هيڅکله د داسې کار په حقله نۀ دى اورېدلى او نۀ کله داسې کار شوے دے. مونږ به د دې په حقله سوچ وکړُو. مونږ ته ووايئ چې څۀ وکړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6572, 'Judges 20:1', 'Judges', 20, 1, '&nbsp;بيا په شمال کښې د دان نه واخله په جنوب کښې تر بيرسبع پورې، هم داسې نمرخاتۀ طرف ته د جِلعاد د مُلک ټول بنى اِسرائيل راووتل. قوم د يو تن په شان په مصفاه کښې د مالِک خُدائ په حضور کښې راغونډ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6573, 'Judges 20:2', 'Judges', 20, 2, '&nbsp;د بنى اِسرائيلو د ټولو قبيلو مشران د خُدائ پاک د خلقو په دې غونډه کښې حاضر وُو او هلته څلور لاکه فوجيان د تُورو سره ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6574, 'Judges 20:3', 'Judges', 20, 3, '&nbsp;په دې دوران کښې د بنيامين خلق خبر شول چې نور ټول بنى اِسرائيل په مصفاه کښې راغونډ شوى دى. بنى اِسرائيلو تپوس وکړو، ”مونږ ته ووايئ چې دا جرم څنګه شوے دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6575, 'Judges 20:4', 'Judges', 20, 4, '&nbsp;د کوم ليوى چې وينځه وژلے شوې وه هغۀ جواب ورکړو، ”زۀ او زما بله ښځه د بنيامين په علاقه کښې جبعه ته د شپې تېرولو دپاره لاړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6576, 'Judges 20:5', 'Judges', 20, 5, '&nbsp;د جبعې سړى په ما باندې د حملې کولو دپاره راغلل او د کور نه يې ګېره واچوله. د هغوئ اراده زما قتلول وُو، خو هغوئ زما د وينځې سره دومره غلط کار وکړو چې مړه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6577, 'Judges 20:6', 'Judges', 20, 6, '&nbsp;ما د هغې لاش يوړو، ټوټې ټوټې مې کړو او يوه يوه ټوټه مې د بنى اِسرائيلو دولسو قبيلو ته ولېږله. دې خلقو په مونږ کښې سپک او شرمناک کار کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6578, 'Judges 20:7', 'Judges', 20, 7, '&nbsp;تاسو ټول بنى اِسرائيل دلته يئ. نو تاسو فېصله وکړئ چې مونږ له څۀ کول په کار دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6579, 'Judges 20:8', 'Judges', 20, 8, '&nbsp;ټول خلق يو ځائ پاڅېدل او وې وئيل، ”په مونږ کښې به يو کس هم واپس نۀ ځى کۀ هغه په خېمه کښې اوسيږى او کۀ په کور کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6580, 'Judges 20:9', 'Judges', 20, 9, '&nbsp;مونږ به داسې کار وکړُو چې پچه به واچوو او څۀ سړى به خوښ کړُو چې په جبعه باندې حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6581, 'Judges 20:10', 'Judges', 20, 10, '&nbsp;د بنى اِسرائيلو لسمه برخه سړى به لښکر له خوراک رسوى او نور به لاړ شى چې د جبعې نه د دې بې‌شرمه کار بدل واخلى چې هغوئ د بنى اِسرائيل په مُلک کښې کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6582, 'Judges 20:11', 'Judges', 20, 11, '&nbsp;نو د بنى اِسرائيلو ټول سړى د دې يو مقصد دپاره راغونډ شول چې په ښار حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6583, 'Judges 20:12', 'Judges', 20, 12, '&nbsp;د بنى اِسرائيلو قبيلو د بنيامين ټولې علاقې ته پېغام وړُونکى ولېږل چې ووائى، ”دا څومره سخت جرم دے چې ستاسو په مُلک کښې شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6584, 'Judges 20:13', 'Judges', 20, 13, '&nbsp;نو د جبعه دا بدکاره کسان مونږ ته حواله کړئ، چې مونږ يې ووژنو او دا بد عمل د بنى اِسرائيلو نه لرې کړُو.“ خو د بنيامين خلقو خپلو خلقو يعنې بنى اِسرائيلو ته غوږ ونۀ نيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6585, 'Judges 20:14', 'Judges', 20, 14, '&nbsp;هغوئ د بنيامين د ټولو ښارونو نه جبعې ته راغلل چې د نورو بنى اِسرائيلو سره جنګ وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6586, 'Judges 20:17', 'Judges', 20, 17, '&nbsp;د بنيامين د خلقو نه بغېر نورو بنى اِسرائيلى قبيلو څلور لاکه وسله بند فوجيان راغونډ کړل چې کوم ټول تکړه فوجيان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6587, 'Judges 20:18', 'Judges', 20, 18, '&nbsp;بنى اِسرائيل په بيت‌ايل کښې د عبادت ځائ ته لاړل، هلته هغوئ د خُدائ پاک نه تپوس وکړو، ”کومې يوې قبيلې له اول په کار دى چې په بنيامينيانو باندې حمله وکړى؟“ مالِک خُدائ ورته وفرمائيل، ”د يهوداه قبيله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6588, 'Judges 20:19', 'Judges', 20, 19, '&nbsp;نو په ورپسې سحر بنى اِسرائيل روان شول او د جبعې ښار ته نزدې يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6589, 'Judges 20:20', 'Judges', 20, 20, '&nbsp;هغوئ د بنيامين په لښکر باندې حملې کولو له لاړل او ښار ته مخامخ يې د جنګ دپاره د فوجيانو قطارونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6590, 'Judges 20:21', 'Judges', 20, 21, '&nbsp;د بنيامين لښکر د ښار نه بهر راووتلو او د ورځې ختمېدو نه مخکښې هغوئ دوويشت زره بنى اِسرائيلى فوجيان وژلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6591, 'Judges 20:24', 'Judges', 20, 24, '&nbsp;هغوئ په دوېم ځل د بنيامين د لښکر خِلاف روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6592, 'Judges 20:25', 'Judges', 20, 25, '&nbsp;بنيامينيان په دوېم ځل د جبعې نه راووتل او په دې ځل هغوئ اتلس زره وسله بند بنى اِسرائيلى فوجيان ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6593, 'Judges 20:26', 'Judges', 20, 26, '&nbsp;نو ټول بنى اِسرائيل بيت‌ايل ته لاړل او د غم ژړا يې وکړه. هغوئ هلته د مالِک خُدائ په حضور کښې کښېناستل او تر ماښامه پورې يې خوراک نۀ کولو. هغوئ د سلامتۍ نذرانې او څۀ سوزېدونکې نذرانې مالِک خُدائ ته پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6594, 'Judges 20:29', 'Judges', 20, 29, '&nbsp;نو بنى اِسرائيلو د جبعې نه ګېرچاپېره څۀ فوجيان په پټو ځايونو کښې کښېنول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6595, 'Judges 20:30', 'Judges', 20, 30, '&nbsp;نو په درېمه ورځ هغوئ د بنيامين د لښکر خِلاف روان شول او جبعه ته مخامخ يې د جنګ دپاره د فوجيانو صفونه جوړ کړل، لکه څنګه چې يې مخکښې جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6596, 'Judges 20:31', 'Judges', 20, 31, '&nbsp;بنيامينيان د جنګ دپاره راووتل او د ښار نه لرې بوتلے شول. هغوئ د مخکښې په شان په کولاو مېدان کښې د بيت‌ايل په لاره او د جبعې په لاره د څۀ بنى اِسرائيلو وژل شروع کړل او تقريباً دېرش بنى اِسرائيليان يې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6597, 'Judges 20:32', 'Judges', 20, 32, '&nbsp;بنيامينيانو ووئيل، ”مونږ هغوئ له هم هغه شان شکست ورکړو چې څنګه مو مخکښې ورکړے وو.“ خو بنى اِسرائيلو منصوبه جوړه کړې وه چې هغوئ وباسى او په سړکونو باندې يې د ښار نه لرې بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6598, 'Judges 20:33', 'Judges', 20, 33, '&nbsp;نو کله چې د بنى اِسرائيلو غټ لښکر بعل تمر ته ورسېدو نو صفونه يې جوړ کړل. بيا سړى د نمرپرېواتۀ طرف د جبعه ښار ګېرچاپېره د پټو ځايونو نه د جنګ دپاره راووتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6599, 'Judges 20:34', 'Judges', 20, 34, '&nbsp;د بنى اِسرائيلو لسو زرو تکړه فوجيانو په جبعه حمله وکړه او دا سخت جنګ وو. بنيامينيانو ته پته نۀ وه چې د هغوئ تباهى رانزدې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6600, 'Judges 20:35', 'Judges', 20, 35, '&nbsp;مالِک خُدائ بنى اِسرائيلو له د بنيامين په لښکر باندې فتح ورکړه. بنى اِسرائيلو په هغه ورځ باندې پينځويشت زره او سل دشمنان ووژل چا چې تُورې راويستلې وې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');